sys_script_include.script:
var DriveFileAJAX = Class.create();
DriveFileAJAX.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getFile: function() {
        const fileID = this.getParameter("sysparm_file_id");
        const userEmail = !gs.nil(this.getParameter("sysparm_user_email")) ?
            this.getParameter("sysparm_user_email") :
            gs.getUser().getEmail();
        const acknowledgeAbuse = this.getParameter("sysparm_acknowledge_abuse");
        const supportsAllDrives = this.getParameter("sysparm_supports_all_drives");
        const includePermissionsForView = this.getParameter("sysparm_include_permissions_for_view");
        const includeLabels = this.getParameter("sysparm_include_labels");
        const fields = this.getParameter("sysparm_fields");

        const api = new x_neyu_google_nyu.DriveFileAPI();
        const response = api.getFile(fileID, userEmail, {
            acknowledgeAbuse: acknowledgeAbuse,
            supportsAllDrives: supportsAllDrives,
            includePermissionsForView: includePermissionsForView,
            includeLabels: includeLabels,
            fields: fields
        });

        if (!response.error && response.status == 200) {
            const {
                responseBody,
                status
            } = response;
            return JSON.stringify({
                error: false,
                errorMessage: "",
                result: JSON.parse(responseBody),
                status: status
            });
        } else {
            const {
                status,
                errorMessage,
                responseBody
            } = response;
            return JSON.stringify({
                error: true,
                status: status,
                errorMessage: (
                    !gs.nil(errorMessage) ?
                    errorMessage :
                    JSON.parse(responseBody)
                ),
                result: null
            });
        }
    },

    type: 'DriveFileAJAX'
});
